def _from_ihtajja():
    m = json.loads((ROOT / "content/samples/khasais-asl-al-lugha/morphology.json").read_text(encoding="utf-8"))["verbs"]["ihtajja"]
    sw = lambda s: s.replace("ح", "ه").replace("ج", "م")
    e = {k: ([sw(x) for x in v] if isinstance(v, list) else sw(v) if isinstance(v, str) and k not in ("bab", "wazn") else v) for k, v in m.items()}
    e["masdar"], e["ismFail"] = "اِهْتِمَام", "مُهْتَمّ"
    e["note"] = "مُضَعَّفٌ: يُدْغَمُ الْمِثْلَانِ مَا تَحَرَّكَ الثَّانِي (اهْتَمَّ يَهْتَمُّ) وَيُفَكَّانِ أَمَامَ السَّاكِنِ (اِهْتَمَمْتُ) — عَلَى خَلَايَا «اِحْتَجَّ» الْمُخَزَّنَةِ."
    return e
